{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C09","C15","C16","C07","C10","C17","C30","C33","C35","C39","C44","C34"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C09","C15","C16","C07","C10","C17","C30","C33","C35","C39","C44"],
  "claims": [
    {
      "claim": "Under fed high-fat conditions, ziprasidone—a lipophilic, poorly soluble drug—had absolute oral bioavailability of approximately 59–60%, showing that a challenging solubility/lipophilicity profile can still meet F≥20% when food enhances absorption.",
      "card_ids": ["C09","C15","C16"]
    },
    {
      "claim": "Sertindole, another lipophilic, poorly soluble antipsychotic, had oral bioavailability of approximately 74–75% that was not significantly affected by food; tablet-to-solution relative bioavailability was almost unity, reinforcing adequate absorption.",
      "card_ids": ["C07","C10","C17","C30"]
    },
    {
      "claim": "L3 oral-exposure records for the closely related azole antifungals posaconazole and ketoconazole show substantial systemic exposure after oral dosing, including posaconazole Cmax ~605–851 ng/mL and AUC up to 8619 ng·h/mL under fed/steady-state conditions; this supports meaningful oral absorption for the query's azole scaffold.",
      "card_ids": ["C33","C35","C39","C44","C34"]
    },
    {
      "claim": "No L1–L3 record provides affirmative threshold-relevant evidence of F<20% for the query or a close analog; the unfavorable physicochemical prior is not an endpoint measurement and is insufficient to predict low.",
      "card_ids": []
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C33","C34","C35","C36","C37","C38","C39","C40","C41","C42","C43","C44"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is provided for the query molecule (an itraconazole-like azole antifungal) or a structurally identical analog.",
    "L3 records report oral AUC/Cmax for posaconazole and ketoconazole without matched IV comparators, so they do not directly quantify F.",
    "The fed-state formulation, dose, and food composition for the query are unspecified; food effects can be formulation-dependent.",
    "High molecular weight, high logD, and low predicted solubility remain uncertainties, but they are not affirmative evidence of F<20%."
  ],
  "decision_summary": "Predicted high (F≥20%) under fed state: fed-condition absolute-F records for ziprasidone (~59–60%) and food-insensitive high-F records for sertindole (~74–75%) provide transferable direction evidence, and L3 oral-exposure records for the closely related azoles posaconazole and ketoconazole show substantial oral systemic exposure, including under fed conditions. No affirmative low-F evidence exists; the unfavorable physicochemical prior alone is insufficient to predict low."
}

